@pytest.mark.parametrize('r,k,depth,reverse',[(7,2,11,False),(13,.5,-9,False),(7,2,0,True)]) def test_actual_source_circle_chains_have_independent_length_and_curve_bounds(r,k,depth,reverse): interval=(1,0) if reverse else (0,1) profiles=[LoftProfile((Curve((radius,0),(-radius,0),'arc',dict(center=(0,0),sweep_deg=180),name),),origin=(0,0,z),profile_id=name) for radius,z,name in [(r,0,'a'),(r*k,depth,'b')]] report=flatten_loft(*profiles,[LoftCorrespondence('a','b',interval,interval)]) fit=fit_native_loft_boundaries(report) > rational_whole_parameter_and_global_length(report,fit)
